-- FA-008 Large MSB payment to an alert jurisdiction the customer never said it serves
SELECT 'FA-008' AS rule_id, 'transactions' AS anchor_table, a.id AS anchor_id
FROM transactions AS a
WHERE (a.direction = 'out' AND a.channel = 'wire' AND a.amount_cents >= 2500000 AND a.counterparty_country IN ('cn', 'ae', 'eg', 'ke', 'ug', 'dj') AND a.corridor_expected = 0 AND (a.directing_agent_id IS NOT NULL OR a.customer_segment = 'msb'));
